package com.bank.report.service;

import com.bank.report.dto.SettlementReport;
import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class Java7StyleReportService {

    private final TradeRepository tradeRepo;

    public SettlementReport generateOldWay(LocalDate date) {
        List<Trade> trades = tradeRepo.findByTradeDate(date);

        // Java 7: manual loops, temporary lists, null checks everywhere
        long settled = 0;
        long pending = 0;
        BigDecimal buyTotal = BigDecimal.ZERO;
        BigDecimal sellTotal = BigDecimal.ZERO;
        Map<String, Long> bySymbol = new HashMap<>();

        for (Trade trade : trades) {
            if (trade == null) continue;  // manual null check!

            if ("SETTLED".equals(trade.getStatus())) {
                settled++;
            } else {
                pending++;
            }

            BigDecimal amount = trade.getPrice().multiply(BigDecimal.valueOf(trade.getQuantity()));
            if ("BUY".equals(trade.getSide())) {
                buyTotal = buyTotal.add(amount);
            } else {
                sellTotal = sellTotal.add(amount);
            }

            // Manual counting per symbol
            Long count = bySymbol.get(trade.getSymbol());
            if (count == null) count = 0L;
            bySymbol.put(trade.getSymbol(), count + 1);
        }

        // Sort symbols by count — verbose with Comparator
        List<Map.Entry<String, Long>> entries = new ArrayList<>(bySymbol.entrySet());
        entries.sort(new Comparator<Map.Entry<String, Long>>() {  // anonymous class!
            @Override
            public int compare(Map.Entry<String, Long> a, Map.Entry<String, Long> b) {
                return Long.compare(b.getValue(), a.getValue());
            }
        });
        List<String> topSymbols = new ArrayList<>();
        for (int i = 0; i < Math.min(3, entries.size()); i++) {
            topSymbols.add(entries.get(i).getKey());
        }

        log.info("[JAVA 7] Generated report: 50+ lines of imperative code");
        return new SettlementReport(date, settled, pending, buyTotal, sellTotal,
            buyTotal.subtract(sellTotal), bySymbol, topSymbols, "Java7Style");
    }
}
