// ─── File: .../service/Java8StyleReportService.java ───
// *** NEW WAY: Java 8 — streams, lambdas, Optional, method references ***
package com.bank.report.service;

import com.bank.report.dto.SettlementReport;
import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.stream.Collectors;
import static java.util.stream.Collectors.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class Java8StyleReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public SettlementReport generate(LocalDate date) {
        List<Trade> trades = tradeRepo.findByTradeDate(date);

        // STREAM: count settled vs pending — replaces manual counter
        long settled = trades.stream().filter(Trade::isSettled).count();
        long pending = trades.stream().filter(t -> !t.isSettled()).count();

        // STREAM + REDUCE: total buy/sell amounts — replaces manual accumulator
        BigDecimal buyTotal = trades.stream()
            .filter(Trade::isBuy)
            .map(Trade::getAmount)          // method reference instead of lambda
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal sellTotal = trades.stream()
            .filter(t -> !t.isBuy())
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        // STREAM + groupingBy + counting: trades per symbol — replaces manual Map building
        Map<String, Long> bySymbol = trades.stream()
            .collect(groupingBy(Trade::getSymbol, counting()));

        // STREAM + sorted + limit: top 3 symbols — replaces manual sorting
        List<String> topSymbols = bySymbol.entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .limit(3)
            .map(Map.Entry::getKey)
            .toList();  // Java 16+ immutable list

        log.info("[JAVA 8] Generated report: ~15 lines of declarative streams");
        return new SettlementReport(date, settled, pending, buyTotal, sellTotal,
            buyTotal.subtract(sellTotal), bySymbol, topSymbols, "Java8Style");
    }

    // OPTIONAL: null-safe account lookup — replaces if (x != null)
    public String getAccountHolder(String tradeId) {
        return tradeRepo.findById(tradeId)
            .map(Trade::getAccountId)           // transform if present
            .orElse("UNKNOWN");                 // default if absent
        // Java 7: Trade t = repo.findById(id); if (t != null) return t.getAccountId(); else return "UNKNOWN";
    }

    // java.time: immutable, thread-safe — replaces broken Date/Calendar/SimpleDateFormat
    public LocalDate getSettlementDate(LocalDate tradeDate) {
        // T+1 settlement: add 1 business day
        LocalDate settlement = tradeDate.plusDays(1);
        // DayOfWeek: if Saturday → Monday, if Sunday → Monday
        while (settlement.getDayOfWeek().getValue() > 5) {
            settlement = settlement.plusDays(1);
        }
        return settlement;
        // java.time is IMMUTABLE: tradeDate is NOT modified. Each operation returns NEW object.
        // Thread-safe: no SimpleDateFormat shared-state issues.
    }
}
