@RestController
@RequestMapping("/api/v1/reports")
@RequiredArgsConstructor
public class ReportController {

    private final Java7StyleReportService java7Service;
    private final Java8StyleReportService java8Service;

    @GetMapping("/settlement/java7/{date}")
    public SettlementReport java7(@PathVariable @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date) {
        return java7Service.generateOldWay(date);
    }

    @GetMapping("/settlement/java8/{date}")
    public SettlementReport java8(@PathVariable @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date) {
        return java8Service.generate(date);
    }
}
