package com.bank.report.service;

import com.bank.report.dto.SettlementReport;
import com.bank.report.model.Trade;
import com.bank.report.repository.TradeRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class Java8StyleReportServiceTest {

    @Mock TradeRepository tradeRepo;
    @InjectMocks Java8StyleReportService service;

    @Test
    void shouldGenerateReportWithStreams() {
        Trade t1 = mock(Trade.class);
        when(t1.isSettled()).thenReturn(true);
        when(t1.isBuy()).thenReturn(true);
        when(t1.getAmount()).thenReturn(new BigDecimal("245050"));
        when(t1.getSymbol()).thenReturn("RELIANCE");

        Trade t2 = mock(Trade.class);
        when(t2.isSettled()).thenReturn(true);
        when(t2.isBuy()).thenReturn(false);
        when(t2.getAmount()).thenReturn(new BigDecimal("330150"));
        when(t2.getSymbol()).thenReturn("HDFC");

        when(tradeRepo.findByTradeDate(LocalDate.of(2024, 1, 15))).thenReturn(List.of(t1, t2));

        SettlementReport report = service.generate(LocalDate.of(2024, 1, 15));

        assertThat(report.totalSettled()).isEqualTo(2);
        assertThat(report.totalBuyAmount()).isEqualByComparingTo("245050");
        assertThat(report.totalSellAmount()).isEqualByComparingTo("330150");
        assertThat(report.tradesBySymbol()).containsKeys("RELIANCE", "HDFC");
    }

    @Test
    void shouldCalculateT1SettlementDate() {
        // Friday → Monday (skip weekend)
        LocalDate friday = LocalDate.of(2024, 1, 19);
        assertThat(service.getSettlementDate(friday)).isEqualTo(LocalDate.of(2024, 1, 22));

        // Wednesday → Thursday
        LocalDate wednesday = LocalDate.of(2024, 1, 17);
        assertThat(service.getSettlementDate(wednesday)).isEqualTo(LocalDate.of(2024, 1, 18));
    }

    @Test
    void shouldReturnDefaultForMissingTrade() {
        when(tradeRepo.findById("UNKNOWN")).thenReturn(java.util.Optional.empty());
        assertThat(service.getAccountHolder("UNKNOWN")).isEqualTo("UNKNOWN");
    }
}
